// Loaded only by Django. The hosted static preview keeps its original behavior.
let csrf='',customer=null,serverCart={},addresses=[],orders=[],checkoutKey='',backendReady=false;
const originalRender=render,originalProduct=product;
const originalArt=art;
function escapeHTML(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
art=function(p){return originalArt({...p,name:escapeHTML(p.name)})};
async function api(path,method='GET',data){const response=await fetch('/api/'+path+'/',{method,credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRFToken':csrf},...(data?{body:JSON.stringify(data)}:{})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Unable to complete your request.');return result}
function applySelection(data){serverCart=data.cart;cart=Object.fromEntries(Object.entries(serverCart).map(([key,item])=>[key,item.quantity]));wishlist=data.wishlist;document.querySelector('#count').textContent=Object.values(cart).reduce((a,b)=>a+b,0)}
function money(price){return price==null?'Pricing coming soon':'₹'+Number(price).toFixed(2)}
save=function(){document.querySelector('#count').textContent=Object.values(cart).reduce((a,b)=>a+b,0)};
card=function(p){return `<article>${art(p)}<div class="product-info"><small>${escapeHTML(names[p.cat])}</small><h3><a href="#product/${p.id}">${escapeHTML(p.name)}</a></h3><div class="bottom"><span>${money(p.price)}</span><button data-add="${p.id}">Add to bag +</button></div></div></article>`};
account=function(){return `<section class="page narrow"><span class="eyebrow">MY ACCOUNT</span><h1>${customer?'Welcome, '+escapeHTML(customer.name)+'.':'Your everyday space.'}</h1>${customer?`<p>${escapeHTML(customer.email)}</p><a class="btn" href="#orders">Your orders</a> <button class="btn light" id="logout">Sign out</button><h2>Your delivery addresses</h2><div>${addresses.map(a=>`<div class="notice" style="margin:12px 0"><b>${escapeHTML(a.name)}</b><br>${escapeHTML(a.line1)}, ${escapeHTML(a.city)}, ${escapeHTML(a.state)} ${escapeHTML(a.postcode)}<br>${escapeHTML(a.phone)} <button data-delete-address="${a.id}">Remove</button></div>`).join('')||'<p>No saved addresses yet.</p>'}</div><h3>Add an address</h3><form id="address"><div class="form-grid">${[['name','Recipient name'],['phone','Phone'],['line1','Street address'],['city','City'],['state','State'],['postcode','Postcode']].map(([n,l])=>`<label>${l}<input name="${n}" required maxlength="${n==='line1'?200:n==='phone'?20:n==='postcode'?10:100}"></label>`).join('')}</div><button class="btn">Save address</button></form>`:`<div class="form-grid"><div><h2>Sign in</h2><form id="login"><label>Email<input name="email" type="email" required autocomplete="username"></label><label>Password<input name="password" type="password" required autocomplete="current-password" maxlength="128"></label><p><button class="btn">Sign in</button></p></form></div><div><h2>Create an account</h2><form id="register"><label>Name<input name="name" required maxlength="100" autocomplete="name"></label><label>Email<input name="email" type="email" required maxlength="150" autocomplete="username"></label><label>Password<input name="password" type="password" required minlength="8" maxlength="128" autocomplete="new-password"></label><p>Use a strong password with at least 8 characters.</p><button class="btn">Register</button></form></div></div>`}<p id="form-error" role="alert"></p></section>`};
cartPage=function(){const list=products.filter(p=>cart[p.id]);return `<section class="page narrow"><span class="eyebrow">YOUR EVERYDAY SELECTION</span><h1>Your bag.</h1>${list.length?`${list.map(p=>{const v=p.variants.find(v=>v.id===serverCart[p.id].variant);return `<div class="cart-row"><div><a href="#product/${p.id}">${escapeHTML(p.name)}</a><p>${v?escapeHTML(v.name)+' · ':''}${money(v?v.price:p.price)}</p></div><input type="number" min="1" max="99" value="${cart[p.id]}" data-qty="${p.id}" aria-label="Quantity for ${escapeHTML(p.name)}"><button class="btn light" style="padding:9px" data-remove="${p.id}">Remove</button></div>`}).join('')}<p>Shipping and final purchase terms will be confirmed by our team.</p><a href="#checkout" class="btn">Continue to checkout</a>`:'<div class="empty"><h2>Your bag is empty.</h2><a class="btn" href="#shop">Explore products</a></div>'}</section>`};
checkout=function(){if(!customer)return `<section class="page narrow"><h1>Checkout</h1><p>Sign in to save your request and view its progress.</p><a class="btn" href="#account">Sign in / Register</a></section>`;if(!Object.keys(cart).length)return `<section class="page narrow"><h1>Your bag is empty.</h1><a class="btn" href="#shop">Explore products</a></section>`;return `<section class="page narrow"><span class="eyebrow">YOUR EVERYDAY SELECTION</span><h1>Review & submit.</h1><div class="notice">Unpriced products are submitted as availability enquiries. Priced products are submitted as orders pending confirmation. Online payments are not enabled. Our team will confirm shipping and final purchase terms.</div><p>${products.filter(p=>cart[p.id]).map(p=>`${escapeHTML(p.name)} × ${cart[p.id]}`).join('<br>')}</p>${addresses.length?`<form id="checkout"><label>Delivery address<select name="address_id">${addresses.map(a=>`<option value="${a.id}">${escapeHTML(a.name+', '+a.line1+', '+a.city+' '+a.postcode)}</option>`).join('')}</select></label><div class="form-grid"><label>Coupon code (optional)<input name="coupon" maxlength="40"></label><label>Notes (optional)<textarea name="note" maxlength="2000"></textarea></label></div><button class="btn">Submit request</button></form>`:'<p>Add a delivery address before submitting.</p><a class="btn" href="#account">Add an address</a>'}<p role="alert" id="form-error"></p></section>`};
function ordersPage(){return `<section class="page narrow"><span class="eyebrow">MY ORDERS</span><h1>Order history & tracking.</h1>${customer?orders.map(o=>`<div class="notice" style="margin:20px 0"><b>${escapeHTML(o.status)}</b><p>Reference: ${escapeHTML(o.reference)}<br>${new Date(o.created_at).toLocaleDateString('en-IN')}<br>${o.items.map(i=>`${escapeHTML(i.name)}${i.variant?' — '+escapeHTML(i.variant):''} × ${i.quantity}`).join('<br>')}<br>Total: ${o.total==null?'Awaiting pricing':money(o.total)}<br>Tracking: ${escapeHTML(o.tracking||'Not shipped')}</p></div>`).join('')||'<p>No orders or enquiries yet.</p>':'<p>Sign in to view your orders.</p><a href="#account" class="btn">Sign in</a>'}</section>`}
product=function(id){const p=products.find(p=>p.id===id);if(!p)return originalProduct(id);return `<section class="page"><p><a href="#shop">Shop</a> / ${escapeHTML(names[p.cat])}</p><div class="detail">${art(p)}<div><span class="eyebrow">${escapeHTML(names[p.cat])}</span><h1 style="font-size:44px">${escapeHTML(p.name)}</h1><p>${escapeHTML(p.desc)}</p><p>${money(p.price)}</p>${p.variants.length?`<label>Choose an option<select id="variant">${p.variants.map(v=>`<option value="${v.id}">${escapeHTML(v.name)} — ${money(v.price)}${v.stock===0?' (out of stock)':''}</option>`).join('')}</select></label>`:`<p>${escapeHTML(p.variant)}</p>`}<div class="notice">Packaging is illustrative. Our team will confirm final product information and purchase terms.</div><button class="btn" data-add="${p.id}">Add to bag +</button><button class="btn light" data-buy="${p.id}">Continue to checkout</button><h3>Product reviews</h3><div id="reviews">Loading reviews…</div>${customer?`<form id="review" data-product="${p.id}"><label>Your rating<select name="rating">${[5,4,3,2,1].map(n=>`<option value="${n}">${n} stars</option>`).join('')}</select></label><label>Your review<textarea name="text" required maxlength="2000"></textarea></label><p><button class="btn light">Submit review</button></p></form>`:'<p><a href="#account" class="textlink">Sign in to leave a review</a></p>'}<p id="form-error" role="alert"></p></div></div></section>`};
policies.privacy[1]='Django stores your cart in a session and your account wishlist, addresses and order enquiries in the site database. Passwords are hashed. Session and CSRF cookies keep your account secure. Newsletter subscriptions are saved when you submit your email. Contact our team with questions about your information.';
policies.returns[2]='Online payments are not enabled. Confirmed return and refund terms must be provided before purchasing.';
render=function(){originalRender();const route=location.hash.slice(1);if(route==='orders')app.innerHTML=ordersPage()};
let routeVersion=0;
async function refreshRoute(){if(!backendReady)return;const version=++routeVersion;const route=location.hash.slice(1);try{if(customer&&['account','checkout'].includes(route)){const result=await api('addresses');addresses=result.addresses}if(customer&&route==='orders'){const result=await api('orders');orders=result.orders}if(version!==routeVersion)return;render();if(route.startsWith('product/')){const result=await api('reviews/'+route.split('/')[1]);if(version!==routeVersion)return;const target=document.querySelector('#reviews');if(target)target.innerHTML=result.reviews.length?result.reviews.map(r=>`<div class="notice"><b>${escapeHTML(r.name)} · ${r.rating}/5</b><p>${escapeHTML(r.text)}</p></div>`).join(''):'<p>No customer reviews yet.</p>'}}catch(e){toast(e.message)}}
function showError(e){const error=document.querySelector('#form-error');if(error)error.textContent=e.message;else toast(e.message)}
document.addEventListener('click',async e=>{const target=e.target.closest('[data-add],[data-buy],[data-wish],[data-remove],[data-delete-address],#logout');if(!target)return;e.stopImmediatePropagation();e.preventDefault();if(!backendReady){toast('Connecting to the store. Please try again.');return}target.disabled=true;try{if(target.id==='logout'){const result=await api('logout','POST',{});customer=null;csrf=result.csrf;applySelection(result);addresses=[];orders=[];render();return}if(target.dataset.deleteAddress){await api('addresses/'+target.dataset.deleteAddress,'DELETE',{});await refreshRoute();return}const id=target.dataset.add||target.dataset.buy||target.dataset.wish||target.dataset.remove;if(target.dataset.wish){applySelection(await api('wishlist',wishlist.includes(id)?'DELETE':'POST',{product:id}));await refreshRoute()}else if(target.dataset.remove){applySelection(await api('cart','DELETE',{product:id}));render()}else{const selected=document.querySelector('#variant');const p=products.find(p=>p.id===id);if(p.variants.length&&!selected){location.hash='product/'+id;toast('Choose a product option first.');return}const variant=selected&&selected.value?Number(selected.value):serverCart[id]?.variant??null;applySelection(await api('cart','POST',{product:id,quantity:Math.min(99,(cart[id]||0)+1),variant}));if(target.dataset.buy){checkoutKey=crypto.randomUUID();location.hash='checkout'}else toast('Added to your bag')}}catch(err){showError(err)}finally{target.disabled=false}},true);
document.addEventListener('change',async e=>{if(!e.target.dataset.qty)return;e.stopImmediatePropagation();if(!backendReady)return;try{const id=e.target.dataset.qty;applySelection(await api('cart','POST',{product:id,quantity:Number(e.target.value),variant:serverCart[id]?.variant??null}));render()}catch(err){showError(err);render()}},true);
document.addEventListener('submit',async e=>{const form=e.target;if(!['login','register','address','checkout','review','newsletter'].includes(form.id))return;e.stopImmediatePropagation();e.preventDefault();if(!backendReady){toast('Connecting to the store. Please try again.');return}const button=form.querySelector('button');button.disabled=true;try{const data=Object.fromEntries(new FormData(form));if(['login','register'].includes(form.id)){const result=await api(form.id,'POST',data);customer=result.user;csrf=result.csrf;applySelection(result);await refreshRoute();toast('Signed in successfully.')}else if(form.id==='address'){await api('addresses','POST',data);await refreshRoute();toast('Address saved.')}else if(form.id==='checkout'){checkoutKey ||= crypto.randomUUID();const result=await api('checkout','POST',{...data,address_id:Number(data.address_id),checkout_key:checkoutKey});applySelection(await api('session'));orders=[result,...orders];checkoutKey='';location.hash='orders';toast('Your request has been saved.')}else if(form.id==='review'){await api('reviews','POST',{product:form.dataset.product,rating:Number(data.rating),text:data.text});form.reset();toast('Thank you. Your review is awaiting moderation.')}else{await api('newsletter','POST',{email:document.querySelector('#news-email').value});form.reset();toast('You are subscribed to product updates.')}}catch(err){showError(err)}finally{button.disabled=false}},true);
window.addEventListener('hashchange',refreshRoute);
(async()=>{try{const [catalogData,session]=await Promise.all([api('products'),api('session')]);products.splice(0,products.length,...catalogData.products);csrf=session.csrf;customer=session.user;applySelection(session);backendReady=true;await refreshRoute()}catch(e){app.innerHTML='<section class="page narrow"><h1>Unable to connect.</h1><p>Please refresh the page to try again.</p></section>';toast(e.message)}})();
